{"path":"index.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8" />
  <meta name="viewport" content="width=device-width,initial-scale=1" />
  <title>{{BUSINESS_NAME}} — {{TAGLINE}}</title>
  <meta name="description" content="A playful, premium aromatherapy practice that may support balance and focus through crafted blends and small cohort experiences." />
  <link rel="stylesheet" href="assets/css/styles.css">
</head>
<body class="site-root">
  <svg style="position:absolute;left:-9999px;" width="0" height="0" aria-hidden="true"><defs>
    <linearGradient id="g1" x1="0" x2="1"><stop offset="0" stop-color="#FFEEDD"/><stop offset="1" stop-color="#FFF2EE"/></linearGradient>
  </defs></svg>

  <header class="nav-wrap">
    <div class="container nav-inner">
      <a class="logo" href="/">{{BUSINESS_NAME}}</a>
      <nav class="nav">
        <a href="/">Home</a>
        <a href="/services.html">Offerings</a>
        <a href="/blends.html">Blends</a>
        <a href="/shop.html">Shop</a>
        <a href="/pricing.html">Pricing</a>
        <a href="/about.html">About</a>
        <a href="/book.html" class="cta small-cta">Book</a>
        <a href="/contact.html">Contact</a>
      </nav>
      <button class="mobile-toggle" aria-label="Menu">☰</button>
    </div>
  </header>

  <main>
    <!-- HERO: playful premium -->
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div class="hero-left">
          <h1 class="headline">A little lift for the day — aroma practices that may support calm, focus, and reset.</h1>
          <p class="subhead">Small-group cohorts, tailored blends, and short rituals designed to fit around life. Gentle, safe, and curiosity-forward.</p>

          <div class="hero-ctas">
            <a id="primaryCta" class="primary btn" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
            <a class="ghost btn" href="/services.html">See Programs</a>
          </div>

        </div>
        <div class="hero-right">
          <div class="pattern-card">
            <svg class="pattern" viewBox="0 0 200 200" xmlns="http://www.w3.org/2000/svg">
              <defs>
                <pattern id="p1" width="20" height="20" patternUnits="userSpaceOnUse">
                  <rect width="20" height="20" fill="#FFF8F5" />
                  <path d="M0 10 L10 0 M10 20 L20 10" stroke="#FFD8C2" stroke-width="1" stroke-linecap="round"/>
                </pattern>
              </defs>
              <rect width="100%" height="100%" fill="url(#p1)"/>
            </svg>
            <div class="mood-widget">
              <label for="mood" class="muted">How do you feel right now?</label>
              <div class="mood-options" id="moodOptions">
                <button data-key="stressed" class="mood-btn active">Stressed</button>
                <button data-key="sleepy" class="mood-btn">Sleepy</button>
                <button data-key="scattered" class="mood-btn">Scattered</button>
                <button data-key="need-clarity" class="mood-btn">Need clarity</button>
              </div>
              <div class="mood-recommendation" id="moodRec">
                <strong>Our suggestion:</strong>
                <p id="moodApproach">A short grounding ritual with a calming inhale and a gentle balm roll.</p>
                <a id="moodCta" class="btn small-cta" href="/book.html">Book a quick rhythm</a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </section>

    <!-- STORY: narrative + SVG pattern -->
    <section class="story">
      <div class="container story-inner">
        <div class="story-text">
          <h2>Why scent as a small practice?</h2>
          <p>We think of scent as a tiny instruction — a brief cue that invites your attention to change. Our sessions and blends are crafted to be subtle, intentional, and easy to fold into your day. Everything we do is safety-first and designed to complement your routine; results may vary and are not medical claims.</p>
        </div>
        <div class="story-visual">
          <svg class="hero-pattern" viewBox="0 0 300 120" preserveAspectRatio="none">
            <rect width="100%" height="100%" fill="url(#g1)" />
            <circle cx="40" cy="60" r="20" fill="#FFF3EA"/>
            <circle cx="120" cy="30" r="10" fill="#FFE8D6"/>
            <circle cx="220" cy="80" r="24" fill="#FFF5F0"/>
          </svg>
        </div>
      </div>
    </section>

    <!-- FRAMEWORK: how it works -->
    <section class="framework container">
      <h3 class="section-title">How we work — the simple flow</h3>
      <div class="steps">
        <div class="step">
          <h4>1. Notice</h4>
          <p>Choose your current mood and pick a micro-practice.</p>
        </div>
        <div class="step">
          <h4>2. Blend</h4>
          <p>We match an approach: inhale, roll, or diffuse for 10 minutes.</p>
        </div>
        <div class="step">
          <h4>3. Reflect</h4>
          <p>Short reflection and optional cohort check-in to tune next steps.</p>
        </div>
      </div>
    </section>

    <!-- OFFERS: Cohorts, blends, private sessions -->
    <section class="offers container">
      <h3 class="section-title">Programs & pathways</h3>
      <div class="offer-grid">
        <article class="offer-card">
          <h4>Mini Cohort: Calm Cadence</h4>
          <p class="muted">4-week group series with practical rituals that may support winding down.</p>
        </article>
        <article class="offer-card">
          <h4>Focus Atelier</h4>
          <p class="muted">Small-session lab for blending attention-forward rituals and portable support.</p>
        </article>
        <article class="offer-card">
          <h4>Private Blend Session</h4>
          <p class="muted">One-on-one to craft a personal, safe blend and practice plan.</p>
        </article>
      </div>
    </section>

    <!-- PRICING: comparator with animated numbers -->
    <section class="pricing container">
      <h3 class="section-title">Investments — choose rhythm or package</h3>
      <div class="pricing-top">
        <div class="toggle">
          <span class="muted">Pay cadence:</span>
          <label class="switch">
            <input id="priceToggle" type="checkbox">
            <span class="slider"></span>
            <span class="labels"><em>Monthly</em><em>Package</em></span>
          </label>
        </div>
      </div>

      <div class="pricing-grid" id="pricingGrid">
        <div class="price-card">
          <h4>Soothe Sessions</h4>
          <div class="price" data-monthly="45" data-package="150">$45</div>
          <p class="muted">Single session that may support decompression.</p>
          <a class="btn" href="/book.html">Reserve</a>
        </div>
        <div class="price-card">
          <h4>Rhythm Workshop</h4>
          <div class="price" data-monthly="95" data-package="350">$95</div>
          <p class="muted">Monthly cohort that may support steady practice.</p>
          <a class="btn" href="/services.html">Join cohort</a>
        </div>
        <div class="price-card">
          <h4>Blend & Keep</h4>
          <div class="price" data-monthly="25" data-package="80">$25</div>
          <p class="muted">Personal blend + guidance; safe dilution recommended.</p>
          <a class="btn" href="/shop.html">Order</a>
        </div>
      </div>
    </section>

    <!-- TESTIMONIALS -->
    <section class="testimonials container">
      <h3 class="section-title">Small notes from members</h3>
      <div class="t-grid">
        <blockquote class="t">"Short sessions that actually fit my lunch break — a calm little reset."</blockquote>
        <blockquote class="t">"Loved the group; the blend we made is subtle and helpful."</blockquote>
      </div>
    </section>

    <!-- FAQ + Safety -->
    <section class="faq container">
      <h3 class="section-title">Safety & common questions</h3>
      <div class="faq-grid">
        <div>
          <h4>Are these medical treatments?</h4>
          <p class="muted">No. Our practices and products are intended to be supportive; they may support wellbeing but are not medical interventions.</p>
        </div>
        <div>
          <h4>Dilution & patch tests</h4>
          <p class="muted">We recommend proper dilution and a patch test before topical use. We'll provide dilution guidance in every session.</p>
        </div>
        <div>
          <h4>Pets & pregnancy</h4>
          <p class="muted">Certain essential oils can affect pets and may not be appropriate during pregnancy. We offer alternatives and will adapt recommendations.</p>
        </div>
      </div>
    </section>

    <!-- CTA -->
    <section class="cta container">
      <div class="cta-wrap">
        <h3>Ready to try a micro-practice?</h3>
        <p class="muted">Reserve a spot in a cohort or book a private blend. No pressure—just practical scents and a warm welcome.</p>
        <a class="primary large" href="{{PRIMARY_CTA_URL}}">{{PRIMARY_CTA_LABEL}}</a>
      </div>
    </section>

  </main>

  <footer class="site-footer">
    <div class="container footer-grid">
      <div>
        <strong>{{BUSINESS_NAME}}</strong>
        <p class="muted">{{CITY}}, {{STATE}} • <a href="tel:{{PHONE}}">{{PHONE}}</a></p>
      </div>
      <div>
        <a href="/about.html">About</a>
        <a href="/contact.html">Contact</a>
        <a href="/pricing.html">Pricing</a>
      </div>
      <div>
        <p class="muted">Email: <a href="mailto:{{EMAIL}}">{{EMAIL}}</a></p>
      </div>
    </div>
  </footer>

  <script src="assets/js/main.js"></script>
</body>
</html>"} 
