{"path":"assets/css/styles.css","content":"/* Bold playful theme — single-file CSS */
:root{
  --bg:#fffaf6; --muted:#6b6b6b; --accent:#ffb07a; --accent-2:#ffd6b3; --ink:#2b2b2b; --radius:12px; --glass: rgba(255,255,255,0.6);
}
*{box-sizing:border-box}
body{font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, 'Helvetica Neue', Arial; margin:0; color:var(--ink); background:var(--bg); -webkit-font-smoothing:antialiased}
.container{max-width:980px;margin:0 auto;padding:28px}
.nav-wrap{background:linear-gradient(180deg, #fff9f4 0%, #fff7f1 100%);border-bottom:1px solid #ffe9d8}
.nav-inner{display:flex;align-items:center;justify-content:space-between}
.logo{font-weight:700;color:var(--ink);text-decoration:none;padding:12px 0}
.nav a{margin:0 8px;color:var(--ink);text-decoration:none;font-weight:600}
.nav .cta{background:var(--accent);color:#fff;padding:8px 12px;border-radius:8px}
.mobile-toggle{display:none;background:transparent;border:none;font-size:20px}

.hero{padding:40px 0}
.hero-grid{display:grid;grid-template-columns:1fr 360px;gap:28px;align-items:center}
.headline{font-size:28px;margin:0 0 12px}
.subhead{color:var(--muted);margin:0 0 18px}
.btn{display:inline-block;padding:10px 14px;border-radius:10px;text-decoration:none;color:var(--ink);background:transparent;border:1px solid rgba(0,0,0,0.06);font-weight:600}
.primary{background:var(--accent);color:#fff;border:none}
.small-cta{padding:6px 9px;border-radius:8px}
.ghost{background:transparent;border:1px solid #ffe1cc}

.pattern-card{background:linear-gradient(180deg,#fff7f0, #fffaf6);border-radius:14px;padding:14px;box-shadow:0 8px 20px rgba(0,0,0,0.04)}
.mood-widget{margin-top:10px}
.mood-options{display:flex;gap:8px;margin:8px 0}
.mood-btn{background:#fff;border:1px solid #ffd9c0;padding:6px 10px;border-radius:8px;cursor:pointer}
.mood-btn.active{background:var(--accent);color:#fff}
.mood-recommendation{background:var(--glass);padding:10px;border-radius:10px;margin-top:10px}
.mood-recommendation p{margin:6px 0}

.story{padding:26px 0}
.story-inner{display:flex;gap:20px;align-items:center}
.story-text{flex:1}
.story-visual{width:320px}

.framework{padding:10px 0}
.steps{display:flex;gap:18px}
.step{background:#fff;border-radius:12px;padding:12px;flex:1;box-shadow:0 6px 14px rgba(0,0,0,0.04)}

.offers{padding:10px 0}
.offer-grid{display:flex;gap:14px}
.offer-card{flex:1;padding:12px;border-radius:12px;background:linear-gradient(180deg,#fff,#fff9f6)}

.pricing{padding:20px 0}
.toggle{display:flex;align-items:center;gap:12px}
.switch{display:inline-flex;align-items:center;gap:8px}
.switch input{display:none}
.slider{width:56px;height:28px;background:#ffdcc0;border-radius:20px;position:relative}
.slider:after{content:"";position:absolute;top:4px;left:4px;width:20px;height:20px;background:#fff;border-radius:50%;transition:all .28s}
.switch input:checked + .slider{background:#ff9d5a}
.switch input:checked + .slider:after{transform:translateX(28px)}
.slider + .labels{font-size:12px;display:inline-flex;gap:8px;color:var(--muted)}
.pricing-grid{display:flex;gap:12px;margin-top:16px}
.price-card{flex:1;padding:16px;background:#fff;border-radius:12px;text-align:center}
.price{font-size:22px;font-weight:800;margin:10px 0}

.testimonials{padding:10px 0}
.t-grid{display:flex;gap:12px}
.t{background:#fff;padding:14px;border-radius:12px}

.faq{padding:14px 0}
.faq-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}

.cta{padding:26px 0}
.cta-wrap{background:linear-gradient(180deg,#fffefc,#fff9f3);padding:20px;border-radius:16px;text-align:center}
.site-footer{border-top:1px solid #ffe9d8;padding:18px 0;margin-top:40px}
.footer-grid{display:flex;justify-content:space-between;align-items:center}
.muted{color:var(--muted)}

/* Responsive */
@media (max-width:900px){
  .hero-grid{grid-template-columns:1fr}
  .nav{display:none}
  .mobile-toggle{display:block}
  .offer-grid{flex-direction:column}
  .pricing-grid{flex-direction:column}
  .steps{flex-direction:column}
  .story-inner{flex-direction:column}
  .faq-grid{grid-template-columns:1fr}
}
"} 
{"path":"assets/js/main.js","content":"// Main JS: pricing comparator + mood-to-method selector + small UI helpers
(function(){
  // Utilities
  function $(sel, ctx){return (ctx||document).querySelector(sel)}
  function $all(sel, ctx){return Array.from((ctx||document).querySelectorAll(sel))}

  // Mobile nav
  const mobileToggle = $('.mobile-toggle');
  const nav = document.querySelector('.nav');
  mobileToggle && mobileToggle.addEventListener('click', function(){
    if(nav.style.display==='flex'){nav.style.display='none'}else{nav.style.display='flex';nav.style.flexDirection='column'}
  });

  // Pricing Comparator
  const priceToggle = $('#priceToggle');
  const priceEls = $all('.price');
  let animFrame = null;

  function animateNumber(el, start, end, duration){
    const startTime = performance.now();
    cancelAnimationFrame(animFrame);
    function tick(now){
      const t = Math.min(1,(now - startTime)/duration);
      const eased = t<.5 ? 2*t*t : -1 + (4-2*t)*t; // simple ease
      const val = Math.round(start + (end - start) * eased);
      el.textContent = '$' + val;
      if(t<1) animFrame = requestAnimationFrame(tick);
    }
    animFrame = requestAnimationFrame(tick);
  }

  function updatePrices(usePackage){
    priceEls.forEach(el=>{
      const monthly = parseInt(el.getAttribute('data-monthly'),10);
      const pack = parseInt(el.getAttribute('data-package'),10);
      const currentText = el.textContent.replace(/[^0-9]/g,'');
      const current = currentText?parseInt(currentText,10): (usePackage?monthly:pack);
      const target = usePackage?pack:monthly;
      animateNumber(el,current,target,500);
    });
  }

  if(priceToggle){
    priceToggle.addEventListener('change', function(){
      updatePrices(this.checked);
    });
    // initial state: monthly
    updatePrices(false);
  }

  // Mood-to-Method selector
  const moodOptions = $('#moodOptions');
  const moodRec = $('#moodApproach');
  const moodCta = $('#moodCta');
  const primaryCta = $('#primaryCta');

  const moodMap = {
    'stressed':{
      text: 'A 5–10 minute grounding inhale sequence with a calming roll-on to support unwinding.',
      cta: {label: 'Book a grounding session', url: '/book.html#grounding'}
    },
    'sleepy':{
      text: 'Gentle uplifting citrus notes and a brief breathing pattern to invite wakefulness.',
      cta: {label: 'Try a morning micro-practice', url: '/services.html#morning'}
    },
    'scattered':{
      text: 'Short focus ritual: a focused inhale, pause, and single-task prompt with a blend to assist attention.',
      cta: {label: 'Join a Focus Atelier', url: '/services.html#focus'}
    },
    'need-clarity':{
      text: 'Clarity mini: a simple ritual to map priorities and a clarifying diffuse for 10 minutes.',
      cta: {label: 'Explore clarity options', url: '/offers.html'}
    }
  };

  function setMood(key, el){
    // update active state
    $all('.mood-btn').forEach(b=>b.classList.remove('active'));
    el.classList.add('active');
    const info = moodMap[key];
    moodRec.textContent = info.text;
    moodCta.textContent = info.cta.label;
    moodCta.setAttribute('href', info.cta.url);
    // also morph the main CTA phrasing briefly
    primaryCta.textContent = info.cta.label;
    primaryCta.setAttribute('href', info.cta.url);
    primaryCta.classList.add('pulse');
    setTimeout(()=>primaryCta.classList.remove('pulse'),800);
  }

  if(moodOptions){
    $all('.mood-btn', moodOptions).forEach(btn=>{
      btn.addEventListener('click', function(e){
        const key = this.getAttribute('data-key');
        setMood(key, this);
      });
    });
  }

  // Initialize with first mood selected
  (function initMood(){
    const first = $all('.mood-btn')[0];
    first && first.click();
  })();

  // Small visual class for CTA pulse
  const style = document.createElement('style');
  style.textContent = '.pulse{animation:pulse 0.8s ease} @keyframes pulse{0%{transform:scale(1)}50%{transform:scale(1.05)}100%{transform:scale(1)}}';
  document.head.appendChild(style);

})();"} 
